import {migratedByPath,isReleased} from '@/lib/migrated-content';
import {MigratedGuide} from '@/components/migrated-guide';
import {formatEditorialDate} from '@/lib/editorial-dates';
import {contentUpdated} from '@/lib/seo-pages';
import Image from '@/components/content-image';
import {editorialImages} from '@/lib/editorial-images';
import {PageSchema} from '@/components/page-schema';
import Link from 'next/link';
import {notFound} from 'next/navigation';
import {articles} from '@/lib/articles';
import {relatedArticles} from '@/lib/service-reading';
import {services} from '@/lib/content';
import {metadata as makeMetadata} from '@/lib/seo';
import {PageHero,CTA,CheckList,Eyebrow,FAQ} from '@/components/ui';
export const dynamic='force-dynamic';

export async function generateMetadata({params}:{params:Promise<{slug:string}>}){const{slug}=await params;const a=articles.find(x=>x.slug===slug);const e=migratedByPath.get(`/resources/${slug}/`);if(!a&&(!e||!isReleased(e)))notFound();return a?makeMetadata(a.title,a.summary,`/resources/${slug}/`):makeMetadata(e!.title,e!.summary,e!.path)}
export default async function ArticlePage({params}:{params:Promise<{slug:string}>}){const{slug}=await params;const a=articles.find(x=>x.slug===slug);if(!a){const e=migratedByPath.get(`/resources/${slug}/`);if(!e||!isReleased(e))notFound();return <MigratedGuide entry={e}/>;}return <><PageSchema path={`/resources/${slug}/`}/><PageHero eyebrow={a.category} title={a.title} description={a.summary} crumbs={[{label:'Blog',href:'/resources/'},{label:a.title}]}><div className="article-meta"><span>Wonderweb Studio editorial team</span>{a.published?<span>Published <time dateTime={a.published}>{formatEditorialDate(a.published)}</time></span>:null}<span>Updated <time dateTime={a.updated||contentUpdated}>{formatEditorialDate(a.updated||contentUpdated)}</time></span><span>{a.readTime}</span></div></PageHero><section className="section cream"><div className="container article-layout"><aside className="article-sidebar"><span>In this guide</span>{a.sections.map((s,i)=><a href={`#section-${i+1}`} key={s.title}>{s.title}</a>)}</aside><article className="prose"><Image src={editorialImages[slug].src} alt={editorialImages[slug].alt} width={1440} height={810} sizes="(max-width:700px) 90vw,65vw" style={{width:'100%',height:'auto',borderRadius:20,marginBottom:32}}/>{a.sections.map((s,i)=><section id={`section-${i+1}`} key={s.title}><h2>{s.title}</h2>{s.body.split(/\n\n+/).map((paragraph,j)=><p key={j}>{paragraph}</p>)}{s.links?.length?<div className="article-context-links">{s.links.map(link=><Link key={link.href} href={link.href}>{link.label}</Link>)}</div>:null}</section>)}<div className="article-checklist"><h2>Your next-step checklist</h2><CheckList items={a.checklist}/></div>{a.faqs?<div className="article-faq"><h2>Frequently asked questions</h2><FAQ items={a.faqs}/></div>:null}{a.sources?<div className="article-sources"><strong>Further reading</strong>{a.sources.map(s=><a key={s.url} href={s.url} target="_blank" rel="noopener noreferrer">{s.title}</a>)}</div>:null}<div className="article-related-reading"><h2>Keep exploring</h2>{relatedArticles(a).map(other=><Link key={other.slug} href={`/resources/${other.slug}/`}>{other.title}</Link>)}</div></article></div></section><section className="section"><div className="container"><Eyebrow>PUT THE IDEA TO WORK</Eyebrow><h2>Need a hand with the next step?</h2><div className="related-grid">{a.related.map(r=>services.find(x=>x.slug===r)!).map(s=><Link className="directory-card dark-card" key={s.slug} href={`/services/${s.slug}/`}><h3>{s.title}</h3><p>{s.intro}</p></Link>)}</div></div></section><CTA/></>}
