import Link from 'next/link';
import Image from './content-image';
import {PageSchema} from './page-schema';
import {PageHero,CTA,FAQ} from './ui';
import {formatEditorialDate} from '@/lib/editorial-dates';
import {migrationCover,publishedMigrations,type MigratedEntry} from '@/lib/migrated-content';
import {serviceReading} from '@/lib/service-reading';
import {migratedDocument} from '@/lib/migrated-body';

export function MigratedGuide({entry}:{entry:MigratedEntry}) {
 const doc=migratedDocument(entry);
 const related=publishedMigrations().filter(e=>e.path!==entry.path&&e.service===entry.service).slice(0,4);const guides=serviceReading(entry.service).slice(0,3);
 return <><PageSchema path={entry.path}/><PageHero eyebrow={entry.category} title={entry.title} description={entry.summary} crumbs={[{label:entry.kind==='resources'?'Blog & guides':'Industry service guides',href:entry.kind==='resources'?'/resources/':'/solutions/'},{label:entry.title}]}><div className="article-meta"><span>Wonderweb Studio editorial team</span><span>Original publication <time dateTime={entry.originalPublished}>{formatEditorialDate(entry.originalPublished)}</time></span><span>Wonderweb adaptation <time dateTime={entry.published}>{formatEditorialDate(entry.published.slice(0,10))}</time></span>{doc.editorialReview?.status==='rewritten'?<span>Rewritten <time dateTime={doc.editorialReview.reviewed}>{formatEditorialDate(doc.editorialReview.reviewed)}</time></span>:null}<span>{entry.readTime}</span></div></PageHero><section className="section cream"><div className="container article-layout"><aside className="article-sidebar"><span>In this guide</span>{doc.headings.map(h=><a href={`#${h.id}`} key={h.id}>{h.title}</a>)}<Link href={`/services/${entry.service}/`}>Discuss this service</Link></aside><article className="prose migrated-prose"><Image src={migrationCover(entry)} alt={`${entry.title} - Wonderweb Studio editorial guide`} width={1200} height={630} sizes="(max-width:700px) 90vw,65vw"/><p className="editorial-provenance">{doc.editorialReview?.status==='rewritten'?'This guide has been rewritten for Wonderweb Studio with expanded examples, practical decisions and current primary references. Original publication provenance is retained above.':'This guide has been adapted for Wonderweb Studio. The original publication and Wonderweb adaptation dates are shown above. Cost examples and platform details reflect the original context and should be checked against current quotes and documentation.'}</p><div dangerouslySetInnerHTML={{__html:doc.html}}/>{entry.kind==='solutions'?<section className="migration-next-step"><h2>Build a plan around your business</h2><p>Start with your priority service, the area you actually serve and the enquiries your team can handle. Wonderweb Studio can review the website, content and campaign requirements with you, then define the scope, responsibilities and measures of progress in a written proposal.</p><p>Work is delivered remotely. Any locations discussed in this guide are campaign planning examples, not Wonderweb office locations. Results depend on your market, offer, budget and follow-up.</p><Link className="text-link" href={`/services/${entry.service}/`}>Explore the service scope</Link></section>:null}{doc.faqs.length?<div className="article-faq"><h2>Questions at a glance</h2><FAQ items={doc.faqs}/></div>:null}<div className="article-related-reading"><h2>Put the ideas into practice</h2><Link href={`/services/${entry.service}/`}>Explore the service and its starting scope</Link><Link href="/pricing/">Compare current Wonderweb service prices</Link>{guides.map(a=><Link key={a.slug} href={`/resources/${a.slug}/`}>{a.title}</Link>)}<h3>Related industry guides</h3>{related.map(e=><Link href={e.path} key={e.path}>{e.title}</Link>)}</div></article></div></section><CTA/></>;
}
